    <AdminEditorSurface v-model:open="storyEditorOpen" :title="storyForm.title ? `故事工坊 · ${storyForm.title}` : '新建探案故事'" :loading="saving" :drawer-width="1040" ok-text="保存故事草稿" @confirm="saveStory">
