    <a-modal v-model:open="scheduleOpen" title="设置定时发布" ok-text="加入发布队列" :confirm-loading="saving" @ok="confirmSchedule"><p>内容到时会自动发布，并生成一条站内推送。</p><a-date-picker v-model:value="scheduleAt" show-time format="YYYY-MM-DD HH:mm" style="width:100%" /></a-modal>
    <a-modal v-model:open="revisionOpen" :title="`${revisionTarget.title} · 版本记录`" :footer="null" width="760px"><p class="editor-note">恢复历史版本会复制成新的草稿，不会直接覆盖当前儿童端内容。</p><a-table :columns="revisionColumns" :data-source="revisionRecords" :loading="revisionLoading" row-key="id" :pagination="false"><template #bodyCell="{ column, record }"><template v-if="column.key === 'status'"><a-tag :color="statusMeta(record.status).color">{{ statusMeta(record.status).label }}</a-tag></template><template v-else-if="column.key === 'operator'">提交 {{ record.created_by || '系统' }} · 审核 {{ record.reviewed_by || '—' }} · 发布 {{ record.published_by || '—' }}</template><template v-else-if="column.key === 'action'"><a-button type="link" :disabled="record.status === 'DRAFT'" @click="restoreRevision(record)">复制为新草稿</a-button></template></template></a-table></a-modal>
  </div>
