const PanelHeading = defineComponent({ props:{title:String,description:String}, emits:['refresh'], setup(props,{emit}) { return () => h('div',{class:'panel-heading'},[h('div',[h('h2',props.title),h('p',props.description)]),h(Button,{onClick:()=>emit('refresh')},()=>[h(ReloadOutlined),'刷新'])]) } })
const BuilderHeading = defineComponent({ props:{number:String,title:String,button:String},emits:['add'],setup(props,{emit}){return()=>h('div',{class:'builder-heading'},[h('div',[h('span',props.number),h('h3',props.title)]),props.button?h(Button,{size:'small',onClick:()=>emit('add')},()=>[h(PlusOutlined),props.button]):null])}})

const activeTab=ref('acupoints'),overview=reactive({}),saving=ref(false),acupointLoading=ref(false),storyLoading=ref(false),queueLoading=ref(false),releaseLoading=ref(false),acupointError=ref(''),storyError=ref(''),acupointEditorOpen=ref(false),storyEditorOpen=ref(false),scheduleOpen=ref(false),scheduleAt=ref(null),revisionOpen=ref(false),revisionLoading=ref(false),revisionRecords=ref([])
const revisionTarget=reactive({type:'',key:'',title:''})
