const statusOptions=[['全部状态','ALL'],['草稿','DRAFT'],['待审核','IN_REVIEW'],['已审核','APPROVED'],['定时发布','SCHEDULED'],['已发布','PUBLISHED'],['已归档','ARCHIVED']].map(([label,value])=>({label,value}))
const modeledOptions=[{label:'全部就绪状态',value:null},{label:'3D可探案',value:true},{label:'仅图鉴',value:false}]
