const acupointColumns=[{title:'穴位星',key:'name',width:180},{title:'经络',dataIndex:'meridian_name',width:150},{title:'身体区域',dataIndex:'body_area',width:120},{title:'3D状态',key:'ready',width:110},{title:'发布状态',key:'status',width:105},{title:'儿童文化档案',dataIndex:'child_description',ellipsis:true},{title:'操作',key:'action',width:220}]
