const revisionColumns=[{title:'版本',dataIndex:'version_no',width:75},{title:'状态',key:'status',width:105},{title:'操作留痕',key:'operator'},{title:'更新时间',dataIndex:'updated_at',width:170},{title:'操作',key:'action',width:130}]
const acupointPagination=computed(()=>({current:acupointPage.current,pageSize:acupointPage.size,total:acupointPage.total,showSizeChanger:true})),releasePagination=computed(()=>({current:releasePage.current,pageSize:releasePage.size,total:releasePage.total}))
const newAcupoint=()=>({originalCode:'',code:'',pointNumber:1,name:'',pinyin:'',meridianCode:'',meridianName:'',meridianEnglish:'',modelId:'',bodyArea:'经络档案区',standardLocation:'',childLocation:'',childDescription:'',childTraditionalUse:'',safetyTip:'只看3D铜人和文化图卡，不做身体操作；有问题请告诉老师或家长。',sourceName:'项目现有穴位目录',sourceLink:'',traditionalUseSourceName:'',traditionalUseSourceLink:'',positionX:null,positionY:null,positionZ:null,sortOrder:362,enabled:true,status:'DRAFT'}),acupointForm=reactive(newAcupoint())
const newPage=()=>({localId:`${Date.now()}-${Math.random()}`,id:'',title:'',image:'',text:'',tip:''}),newClue=()=>({localId:`${Date.now()}-${Math.random()}`,id:'',name:'',description:''})
const newStory=()=>({originalCode:'',storyCode:'',title:'',subtitle:'',summary:'',coverPath:'',estimatedMinutes:5,linkedAcupoints:[],pages:[newPage(),newPage(),newPage()],clues:[newClue(),newClue()],reasoning:{prompt:'',options:['',''],answer:0,explanation:''},safety:{prompt:'',options:['',''],answer:0,message:'只观察、不模仿，有问题问成人。'},rewards:[{code:'bamboo-slip-shard',name:'竹简碎片',amount:1}],status:'DRAFT'}),storyForm=reactive(newStory())
const hasCoordinates=computed(()=>[acupointForm.positionX,acupointForm.positionY,acupointForm.positionZ].every(v=>v!==null&&v!==undefined&&v!==''))
const toMedia=(path)=>resolveMediaUrl(path)
async function loadOverview(){Object.assign(overview,await getCopperContentOverview())}
async function loadAcupoints(){acupointLoading.value=true;acupointError.value='';try{Object.assign(acupointPage,await getCopperAcupointPage({page:acupointPage.current,size:acupointPage.size,keyword:acupointQuery.keyword||undefined,status:acupointQuery.status,modeled:acupointQuery.modeled}))}catch(e){acupointError.value=e?.message||'穴位星图加载失败'}finally{acupointLoading.value=false}}
async function loadStories(){storyLoading.value=true;storyError.value='';try{Object.assign(storyPage,await getCopperStoryPage({page:storyPage.current,size:storyPage.size,keyword:storyQuery.keyword||undefined,status:storyQuery.status}))}catch(e){storyError.value=e?.message||'故事工坊加载失败'}finally{storyLoading.value=false}}
async function loadQueue(){queueLoading.value=true;try{const [ar,aa,as,sr,sa,ss]=await Promise.all([getCopperAcupointPage({page:1,size:50,status:'IN_REVIEW'}),getCopperAcupointPage({page:1,size:50,status:'APPROVED'}),getCopperAcupointPage({page:1,size:50,status:'SCHEDULED'}),getCopperStoryPage({page:1,size:50,status:'IN_REVIEW'}),getCopperStoryPage({page:1,size:50,status:'APPROVED'}),getCopperStoryPage({page:1,size:50,status:'SCHEDULED'})]);queueRecords.value=[...[...ar.records,...aa.records,...as.records].map(i=>({queueKey:`a-${i.code}`,contentType:'acupoints',contentKey:i.code,title:`${i.name} · ${i.code}`,version:i.version_no,status:i.status,scheduledAt:i.scheduled_at,publishError:i.publish_error})),...[...sr.records,...sa.records,...ss.records].map(i=>({queueKey:`s-${i.story_code}`,contentType:'stories',contentKey:i.story_code,title:i.title,version:i.version_no,status:i.status,scheduledAt:i.scheduled_at,publishError:i.publish_error}))]}finally{queueLoading.value=false}}
async function loadReleases(){releaseLoading.value=true;try{Object.assign(releasePage,await getCopperContentReleases({page:releasePage.current,size:releasePage.size}))}finally{releaseLoading.value=false}}
function handleTabChange(key){if(key==='stories')loadStories();if(key==='queue')loadQueue();if(key==='releases')loadReleases()}
function handleAcupointPage(p){acupointPage.current=p.current;acupointPage.size=p.pageSize;loadAcupoints()}function handleReleasePage(p){releasePage.current=p.current;releasePage.size=p.pageSize;loadReleases()}
function openNewAcupoint(){Object.assign(acupointForm,newAcupoint());acupointEditorOpen.value=true}async function editAcupoint(row){const d=await getCopperAcupoint(row.code);Object.assign(acupointForm,newAcupoint(),d,{originalCode:row.code});acupointEditorOpen.value=true}
async function saveAcupoint(){if(!acupointForm.code||!acupointForm.name||!acupointForm.meridianName||!acupointForm.childLocation||!acupointForm.childDescription)return message.warning('请补齐必填内容');if(hasCoordinates.value&&(!acupointForm.childTraditionalUse||!acupointForm.traditionalUseSourceName))return message.warning('3D穴位必须补齐儿童传统用途和来源');saving.value=true;try{const p={...acupointForm};['originalCode','status','validation','versionNo','revisionId','scheduledAt','publishedAt'].forEach(k=>delete p[k]);await saveCopperAcupointDraft(acupointForm.code,p);message.success('穴位草稿已保存');acupointEditorOpen.value=false;await refreshAll()}finally{saving.value=false}}
function openNewStory(){Object.assign(storyForm,newStory());storyEditorOpen.value=true}async function editStory(row){const d=await getCopperStory(row.story_code);Object.assign(storyForm,newStory(),d,{originalCode:row.story_code,pages:(d.pages||[]).map(i=>({...i,localId:i.id||`${Date.now()}-${Math.random()}`})),clues:(d.clues||[]).map(i=>({...i,localId:i.id||`${Date.now()}-${Math.random()}`}))});storyEditorOpen.value=true}function addStoryPage(){storyForm.pages.push(newPage())}function addStoryClue(){storyForm.clues.push(newClue())}
async function saveStory(){if(!storyForm.storyCode||!storyForm.title||!storyForm.summary||storyForm.pages.length<3||storyForm.clues.length<2)return message.warning('请补齐故事、3个场景和2条线索');saving.value=true;try{const p=JSON.parse(JSON.stringify(storyForm));['originalCode','status','validation','versionNo','revisionId','scheduledAt','publishedAt'].forEach(k=>delete p[k]);p.pages.forEach((i,n)=>{delete i.localId;i.id||=`scene-${n+1}`});p.clues.forEach((i,n)=>{delete i.localId;i.id||=`clue-${n+1}`});await saveCopperStoryDraft(storyForm.storyCode,p);message.success('故事草稿已保存');storyEditorOpen.value=false;await refreshAll()}finally{saving.value=false}}
async function runTransition(type,key,action){const label={submit:'提交审核',approve:'审核通过',publish:'立即发布',archive:'归档撤下'}[action];Modal.confirm({title:`确认${label}？`,content:action==='publish'?'发布后儿童端立即可见，并生成站内推送。':'系统会记录操作人和时间。',okText:label,async onOk(){await transitionCopperContent(type,key,action);message.success(`${label}成功`);await refreshAll()}})}
function openSchedule(type,key){Object.assign(scheduleTarget,{type,key});scheduleAt.value=dayjs().add(30,'minute');scheduleOpen.value=true}async function confirmSchedule(){if(!scheduleAt.value||!scheduleAt.value.isAfter(dayjs()))return message.warning('请选择未来时间');saving.value=true;try{await transitionCopperContent(scheduleTarget.type,scheduleTarget.key,'schedule',{scheduledAt:scheduleAt.value.format('YYYY-MM-DD HH:mm:ss')});message.success('已加入定时发布队列');scheduleOpen.value=false;await refreshAll()}finally{saving.value=false}}
async function openRevisions(type,key,title){Object.assign(revisionTarget,{type,key,title});revisionOpen.value=true;revisionLoading.value=true;try{revisionRecords.value=await getCopperContentRevisions(type,key)}finally{revisionLoading.value=false}}
async function restoreRevision(record){Modal.confirm({title:`恢复 v${record.version_no} 为新草稿？`,content:'当前已发布内容不会被覆盖，需重新提交审核和发布。',okText:'复制为草稿',async onOk(){await restoreCopperContentRevision(revisionTarget.type,revisionTarget.key,record.version_no);message.success('历史版本已复制为新草稿');revisionOpen.value=false;await refreshAll()}})}
async function refreshAll(){await Promise.all([loadOverview(),loadAcupoints(),loadStories()]);if(activeTab.value==='queue')await loadQueue();if(activeTab.value==='releases')await loadReleases()}
onMounted(()=>Promise.all([loadOverview(),loadAcupoints()]))
</script>

